mapper.update:
UPDATE projects SET subject = #{subject}, content = #{content}, start_at = TO_DATE(#{start_date}, 'YYYY-MM-DD'), 
	"END" = TO_DATE(#{end_date}, 'YYYY-MM-DD'), status = #{status}, updated = SYSDATE
WHERE workspace_id = #{workspace_id}

mapper.select:
		SELECT p.project_id AS id, p.subject, p.content,  p.created
        FROM projects p
        JOIN workspace_domains wd ON p.workspace_id = wd.workspace_id
        WHERE wd.domain_key = #{domainKey} 
          AND p.project_id = #{id}
          AND p.deleted IS NULL
